function NumberRoll({ value }: { value: number }) {
  const [shown, setShown] = useState(value);
  const prev = useRef(value);
  useEffect(() => {
    if (prev.current === value) return;
    prev.current = value;
    if (reducedMotion()) {
      setShown(value);
      return;
    }
    let n = 0;
    const id = setInterval(() => {
      n++;
      if (n >= 7) {
        clearInterval(id);
        setShown(value);
      } else setShown(Math.floor(Math.random() * 100));
    }, 32);
    return () => {
      clearInterval(id);
      setShown(value);
    };
  }, [value]);
  return <>{String(shown).padStart(2, "0")}</>;
}

function Panel(props: { title: string; tag?: string; children: React.ReactNode; right?: React.ReactNode }) {
  return (
    <section className="panel">
      <div className="panel-head">
        <h2>{props.title}</h2>
        {props.right}
        {props.tag && <span className="tag">{props.tag}</span>}
      </div>
      {props.children}
    </section>
  );
}

/* ------------------------------------------------------------------ */
/* Terrain map                                                         */
/* ------------------------------------------------------------------ */

function TerrainCanvas({ site, sunAz, lit }: { site: P.Site; sunAz: number; lit: boolean }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const N = 420;
  const field = useMemo(() => {
    const z = new Float32Array(N * N);
    let lo = Infinity;
    let hi = -Infinity;
    for (let py = 0; py < N; py++)
      for (let px = 0; px < N; px++) {
        const v = P.patchElevationAt(site, -1050 + ((px + 0.5) / N) * 2100, 1050 - ((py + 0.5) / N) * 2100);
        z[py * N + px] = v;
        if (v < lo) lo = v;
        if (v > hi) hi = v;
      }
    return { z, lo, hi };
  }, [site]);
  const az = Math.round(sunAz / 3) * 3;
  useEffect(() => {
    const ctx = ref.current && ref.current.getContext("2d");
    if (!ctx) return;
    const { z, lo, hi } = field;
    const img = ctx.createImageData(N, N);
    const pxM = 2100 / N;
    // Relief is lit from the Sun's true azimuth (elevation exaggerated to 28 deg so the terrain stays readable).
    const lx = Math.sin(az * P.DEG) * 0.88;
    const ly = Math.cos(az * P.DEG) * 0.88;
    const lz = 0.47;
    const warm = lit ? 1 : 0.55;
    for (let py = 0; py < N; py++)
      for (let px = 0; px < N; px++) {
        const i = py * N + px;
        const zr = z[py * N + Math.min(N - 1, px + 1)];
        const zl = z[py * N + Math.max(0, px - 1)];
        const zu = z[Math.max(0, py - 1) * N + px];
        const zd = z[Math.min(N - 1, py + 1) * N + px];
        const gx = (zr - zl) / (2 * pxM);
        const gy = (zu - zd) / (2 * pxM);
        const shade = P.clamp((-gx * lx - gy * ly + lz) / Math.hypot(gx, gy, 1) / lz, 0, 1.9);
        const t = site.terrain ? (z[i] - lo) / (hi - lo || 1) : 0.25;
        const b = (0.16 + 0.62 * shade) * warm;
        // Neutral regolith grey, like an orbital photograph.
        let r = (78 + 132 * t) * b;
        let g = (77 + 130 * t) * b;
        let bl = (76 + 128 * t) * b * (lit ? 1 : 1.08);
        const c10 = Math.floor(z[i] / 10);
        if (c10 !== Math.floor(zr / 10) || c10 !== Math.floor(zd / 10)) {
          const major = Math.floor(z[i] / 50) !== Math.floor(zr / 50) || Math.floor(z[i] / 50) !== Math.floor(zd / 50);
          const k = major ? 0.5 : 0.2;
          r = r * (1 - k) + 148 * k;
          g = g * (1 - k) + 163 * k;
          bl = bl * (1 - k) + 184 * k;
        }
        img.data[i * 4] = r;
        img.data[i * 4 + 1] = g;
        img.data[i * 4 + 2] = bl;
        img.data[i * 4 + 3] = 255;
      }
    ctx.putImageData(img, 0, 0);
  }, [field, az, lit, site.terrain]);
  return <canvas ref={ref} width={N} height={N} aria-hidden="true" />;
}

function NudgeMap(props: {
  site: P.Site;
  cell: Cell;
  grid: P.CellStatus[];
  month: Float32Array;
  overlay: Overlay;
  haven: { ix: number; iy: number; dist: number } | null;
  pulse?: boolean;
  safe?: Uint8Array | null;
  sunAz: number;
  sunLit: boolean;
  slope: { mean: Float32Array; max: Float32Array; rough: Float32Array };
  onMove: (c: Cell) => void;
}) {
  const { cell, grid, month, overlay, haven } = props;
  const cells = useMemo(() => {
    const out: React.ReactNode[] = [];
    for (let iy = 0; iy < P.GRID_N; iy++)
      for (let ix = 0; ix < P.GRID_N; ix++) {
        const i = iy * P.GRID_N + ix;
        let fill = "#04060e";
        let op = 0;
        if (overlay === "sun") {
          const f = grid[i].sunFrac;
          if (f > 0.02) {
            fill = C.amber;
            op = 0.1 + 0.28 * f;
          } else op = 0.6;
        } else if (overlay === "earth") {
          fill = grid[i].lock === "LOCK" ? C.cyan : grid[i].lock === "GRAZING" ? C.blue : C.crimson;
          op = 0.3;
        } else if (overlay === "slope") {
          const sl = props.slope.max[i];
          fill = sl <= P.SLOPE_SAFE_DEG ? GREEN : sl <= P.SLOPE_LIMIT_DEG ? C.amber : C.crimson;
          op = 0.42;
        } else if (overlay === "none") {
          op = 0;
        } else {
          const p = month[i] / 100;
          fill = `rgb(${Math.round(4 + 241 * p)},${Math.round(6 + 152 * p)},${Math.round(14 - 3 * p)})`;
          op = 0.18 + 0.42 * Math.abs(p - 0.5) * 2 * (p < 0.5 ? 1 : 0.75);
        }
        out.push(<rect key={i} x={ix} y={20 - iy} width={1.02} height={1.02} fill={fill} fillOpacity={op} />);
      }
    return out;
  }, [grid, month, overlay, props.slope]);

  const cx = cell.ix + 0.5;
  const cy = 20 - cell.iy + 0.5;
  const click = (e: React.MouseEvent<HTMLDivElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    const ix = P.clamp(Math.floor(((e.clientX - r.left) / r.width) * 21), 0, 20);
    const iy = P.clamp(20 - Math.floor(((e.clientY - r.top) / r.height) * 21), 0, 20);
    props.onMove({ ix, iy });
  };
  const key = (e: React.KeyboardEvent) => {
    const d: Record<string, [number, number]> = { ArrowUp: [0, 1], ArrowDown: [0, -1], ArrowLeft: [-1, 0], ArrowRight: [1, 0] };
    const m = d[e.key];
    if (!m) return;
    e.preventDefault();
    props.onMove({ ix: P.clamp(cell.ix + m[0], 0, 20), iy: P.clamp(cell.iy + m[1], 0, 20) });
  };
  let arrow: React.ReactNode = null;
  if (haven && (haven.ix !== cell.ix || haven.iy !== cell.iy)) {
    const hx = haven.ix + 0.5;
    const hy = 20 - haven.iy + 0.5;
    const len = Math.hypot(hx - cx, hy - cy);
    const ux = (hx - cx) / len;
    const uy = (hy - cy) / len;
    const tx = hx - ux * 0.5;
    const ty = hy - uy * 0.5;
    arrow = (
      <g className={props.pulse ? "haven-pulse" : ""}>
        <line x1={cx + ux * 0.55} y1={cy + uy * 0.55} x2={tx} y2={ty} stroke={C.gold} strokeWidth={0.16} />
        <polygon
          points={`${hx - ux * 0.1},${hy - uy * 0.1} ${tx - uy * 0.38},${ty + ux * 0.38} ${tx + uy * 0.38},${ty - ux * 0.38}`}
          fill={C.gold}
        />
        <rect x={haven.ix} y={20 - haven.iy} width={1} height={1} fill="none" stroke={C.gold} strokeWidth={0.1} />
      </g>
    );
  }
  return (
    <div
      className="map-wrap"
      onClick={click}
      onKeyDown={key}
      tabIndex={0}
      role="application"
      aria-label="Terrain map. Click a cell or use arrow keys to move the lander in 100 metre steps."
    >
      <TerrainCanvas site={props.site} sunAz={props.sunAz} lit={props.sunLit} />
      <svg viewBox="0 0 21 21" preserveAspectRatio="none">
        {cells}
        {props.safe &&
          Array.from(props.safe).map((v, i) =>
            v ? <rect key={"sf" + i} x={(i % 21) + 0.08} y={20 - Math.floor(i / 21) + 0.08} width={0.84} height={0.84} fill="#22C55E" fillOpacity={0.28} stroke="#22C55E" strokeWidth={0.09} /> : null
          )}
        {arrow}
        <line x1={cx} y1={0} x2={cx} y2={21} stroke="#fff" strokeOpacity={0.35} strokeWidth={0.04} />
        <line x1={0} y1={cy} x2={21} y2={cy} stroke="#fff" strokeOpacity={0.35} strokeWidth={0.04} />
        <circle cx={cx} cy={cy} r={0.52} fill="none" stroke="#fff" strokeOpacity={0.5} strokeWidth={0.07}>
          {!reducedMotion() && <animate attributeName="r" values="0.52;1.5" dur="1.8s" repeatCount="indefinite" />}
          {!reducedMotion() && <animate attributeName="stroke-opacity" values="0.7;0" dur="1.8s" repeatCount="indefinite" />}
        </circle>
        <circle cx={cx} cy={cy} r={0.52} fill="none" stroke="#fff" strokeWidth={0.13} />
        <circle cx={cx} cy={cy} r={0.12} fill="#fff" />
        <g fontSize={0.62} fontFamily="JetBrains Mono, monospace" fill="#E2E8F0">
          <text x={10.5} y={0.8} textAnchor="middle">N</text>
          <line x1={0.6} y1={20.3} x2={5.6} y2={20.3} stroke="#E2E8F0" strokeWidth={0.07} />
          <text x={0.6} y={19.9}>500 m</text>
          {!props.site.terrain && (
            <text x={10.5} y={8} textAnchor="middle" fontSize={0.72}>
              No terrain loaded · smooth-sphere horizon
            </text>
          )}
        </g>
      </svg>
    </div>
  );
}

