/* ------------------------------------------------------------------ */
/* Starfield, polar view, window finder                                */
/* ------------------------------------------------------------------ */

function Starfield() {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const cv = ref.current;
    const ctx = cv && cv.getContext("2d");
    if (!cv || !ctx) return;
    let w = 0;
    let h = 0;
    const stars = Array.from({ length: 220 }, () => ({ x: Math.random(), y: Math.random(), r: Math.random() * 1.2 + 0.2, p: Math.random() * 6.28, s: 0.4 + Math.random() * 1.4 }));
    let shoot: { x: number; y: number; t: number } | null = null;
    const size = () => {
      w = cv.width = window.innerWidth;
      h = cv.height = window.innerHeight;
    };
    size();
    window.addEventListener("resize", size);
    let raf = 0;
    let last = 0;
    const still = reducedMotion();
    const draw = (ms: number) => {
      raf = requestAnimationFrame(draw);
      if (ms - last < 50 && !still) return;
      last = ms;
      ctx.clearRect(0, 0, w, h);
      for (const st of stars) {
        const a = still ? 0.6 : 0.35 + 0.45 * Math.sin(st.p + (ms / 1000) * st.s);
        ctx.fillStyle = `rgba(226,232,240,${a.toFixed(3)})`;
        ctx.beginPath();
        ctx.arc(st.x * w, st.y * h, st.r, 0, 6.28);
        ctx.fill();
      }
      if (still) {
        cancelAnimationFrame(raf);
        return;
      }
      if (!shoot && Math.random() < 0.004) shoot = { x: Math.random() * w * 0.8, y: Math.random() * h * 0.4, t: 0 };
      if (shoot) {
        shoot.t += 0.06;
        const x = shoot.x + shoot.t * 420;
        const y = shoot.y + shoot.t * 170;
        const gr = ctx.createLinearGradient(x - 90, y - 36, x, y);
        gr.addColorStop(0, "rgba(255,255,255,0)");
        gr.addColorStop(1, `rgba(255,255,255,${(0.8 * (1 - shoot.t)).toFixed(2)})`);
        ctx.strokeStyle = gr;
        ctx.lineWidth = 1.4;
        ctx.beginPath();
        ctx.moveTo(x - 90, y - 36);
        ctx.lineTo(x, y);
        ctx.stroke();
        if (shoot.t >= 1) shoot = null;
      }
    };
    raf = requestAnimationFrame(draw);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", size);
    };
  }, []);
  return <canvas ref={ref} className="stars" aria-hidden="true" />;
}

/** Looking down on the south pole: where the sunlight is, where Earth is, where the sites are. */
function PolarView({ eph, siteId }: { eph: P.Ephemeris; siteId: string }) {
  const S = 300;
  const R = 118;
  const c = S / 2;
  const pos = (lat: number, lon: number) => {
    const r = ((90 + lat) / 10) * R;
    return [c + r * Math.sin(lon * P.DEG), c - r * Math.cos(lon * P.DEG)];
  };
  const off = (-eph.subSolarLat / 10) * R;
  const dir = (lon: number, r: number) => [c + r * Math.sin(lon * P.DEG), c - r * Math.cos(lon * P.DEG)];
  const sun = dir(eph.subSolarLon, R + 22);
  const earth = dir(eph.subEarthLon, R + 22);
  return (
    <svg className="chart" viewBox={`0 0 ${S} ${S}`} role="img" aria-label="Map of the south polar cap showing the sunlit half, the direction of Earth and the landing sites">
      <defs>
        <clipPath id="cap">
          <circle cx={c} cy={c} r={R} />
        </clipPath>
        <radialGradient id="pvCore">
          <stop offset="0" stopColor="#FFFFFF" />
          <stop offset="0.6" stopColor="#FFFBEA" />
          <stop offset="1" stopColor="#FBBF24" />
        </radialGradient>
        <radialGradient id="pvHalo">
          <stop offset="0" stopColor="#FFF4C2" stopOpacity="0.7" />
          <stop offset="0.4" stopColor="#FCD34D" stopOpacity="0.22" />
          <stop offset="1" stopColor="#F59E0B" stopOpacity="0" />
        </radialGradient>
        <radialGradient id="capg">
          <stop offset="0" stopColor="#1e293b" />
          <stop offset="1" stopColor="#0b1120" />
        </radialGradient>
      </defs>
      <circle cx={c} cy={c} r={R} fill="url(#capg)" />
      <g clipPath="url(#cap)">
        <rect x={c - 2 * R} y={c - 2 * R} width={4 * R} height={2 * R + off} fill={C.amber} fillOpacity={0.3} transform={`rotate(${eph.subSolarLon} ${c} ${c})`} />
      </g>
      <circle cx={c} cy={c} r={R} fill="none" stroke="#475569" />
      <circle cx={c} cy={c} r={R / 2} fill="none" stroke="#334155" strokeDasharray="2 4" />
      <text x={c + 4} y={c - R / 2 - 3} fontSize={9}>85°S</text>
      <text x={c + 4} y={c - R - 3} fontSize={9}>80°S</text>
      <line x1={c} y1={c} x2={sun[0]} y2={sun[1]} stroke={C.gold} strokeOpacity={0.5} strokeDasharray="3 4" />
<circle cx={sun[0]} cy={sun[1]} r={20} fill="url(#pvHalo)" />
      <circle cx={sun[0]} cy={sun[1]} r={6.5} fill="url(#pvCore)" />
      <text x={sun[0]} y={sun[1] + (sun[1] > c ? 19 : -12)} textAnchor="middle" style={{ fill: C.gold }}>SUN</text>
      <line x1={c} y1={c} x2={earth[0]} y2={earth[1]} stroke={C.cyan} strokeOpacity={0.5} strokeDasharray="3 4" />
      <circle cx={earth[0]} cy={earth[1]} r={6} fill={C.blue} stroke={C.cyan} />
      <text x={earth[0] + 10} y={earth[1] + 4} style={{ fill: C.cyan }}>EARTH</text>
      {P.SITES.filter((s) => s.terrain).map((s) => {
        const [x, y] = pos(s.lat, s.lon);
        const on = s.id === siteId;
        return (
          <g key={s.id}>
            {on && !reducedMotion() && (
              <circle cx={x} cy={y} r={5} fill="none" stroke="#fff">
                <animate attributeName="r" values="4;13" dur="1.8s" repeatCount="indefinite" />
                <animate attributeName="stroke-opacity" values="0.8;0" dur="1.8s" repeatCount="indefinite" />
              </circle>
            )}
            <circle cx={x} cy={y} r={on ? 4.5 : 3} fill={on ? "#fff" : "#94A3B8"} />
            <text
              x={s.id === "malapert" || s.id === "athena" ? x - 8 : x + 8}
              y={s.id === "mouton" ? y - 5 : s.id === "athena" ? y + 12 : y + 4}
              textAnchor={s.id === "malapert" || s.id === "athena" ? "end" : "start"}
              fontSize={10}
              style={{ fill: on ? "#fff" : C.dim, fontSize: 10 }}
            >
              {s.short}
            </text>
          </g>
        );
      })}
      <circle cx={c} cy={c} r={1.6} fill="#fff" />
    </svg>
  );
}

function WindowFinder({ scan, startMs, onPick }: { scan: P.YearScan; startMs: number; onPick: (ms: number) => void }) {
  const best = useMemo(() => P.bestWindows(scan), [scan]);
  const rects = useMemo(() => {
    const out: React.ReactNode[] = [];
    for (let d = 0; d < scan.days; d++) {
      out.push(<rect key={"s" + d} x={d} y={0} width={1.05} height={16} fill={C.amber} fillOpacity={0.08 + 0.92 * (scan.sunPct[d] / 100) ** 1.6} />);
      out.push(<rect key={"e" + d} x={d} y={18} width={1.05} height={16} fill={C.cyan} fillOpacity={0.08 + 0.92 * (scan.earthPct[d] / 100) ** 1.6} />);
      if (scan.nightH[d] >= 48) out.push(<rect key={"n" + d} x={d} y={36} width={1.05} height={6} fill={C.crimson} />);
    }
    return out;
  }, [scan]);
  const months: [number, string][] = [];
  for (let d = 0; d < scan.days; d++) {
    const dt = new Date(startMs + d * DAY);
    if (dt.getUTCDate() === 1) months.push([d, dt.toLocaleDateString("en-GB", { month: "short", timeZone: "UTC" })]);
  }
  return (
    <>
      <div className="spark-rows">
        <div className="wf-labels">
          <span className="amber">SUN</span>
          <span className="cyan">EARTH</span>
          <span className="crimson">48 h+</span>
        </div>
        <svg
          className="wf"
          viewBox={`0 0 ${scan.days} 42`}
          preserveAspectRatio="none"
          role="img"
          aria-label="Twelve month scan of landing dates"
          onClick={(e) => {
            const r = e.currentTarget.getBoundingClientRect();
            onPick(startMs + Math.floor(P.clamp((e.clientX - r.left) / r.width, 0, 0.999) * scan.days) * DAY);
          }}
        >
          {rects}
          {best.map((d) => (
            <rect key={d} x={d} y={0} width={scan.missionDays} height={34} fill="none" stroke="#fff" strokeWidth={1.5} vectorEffect="non-scaling-stroke" />
          ))}
        </svg>
      </div>
      <div className="axis" style={{ position: "relative", height: 14, marginLeft: 52 }}>
        {months.map(([d, m]) => (
          <span key={d} style={{ position: "absolute", left: (d / scan.days) * 100 + "%" }}>{m}</span>
        ))}
      </div>
      <div className="wf-best">
        {best.map((d, i) => (
          <button key={d} className="btn small" onClick={() => onPick(startMs + d * DAY)}>
            <b>#{i + 1}</b> {fmtDay(startMs + d * DAY)} · Sun {scan.sunPct[d].toFixed(0)}% · Earth {scan.earthPct[d].toFixed(0)}% · night {scan.nightH[d].toFixed(0)} h
          </button>
        ))}
      </div>
    </>
  );
}

interface Pin {
  id: number;
  label: string;
  siteId: string;
  cell: Cell;
  baseMs: number;
  delay: number;
  stats: P.TimelineStats;
  slope: number;
}

const BEATS = ["The Eternal Peak Myth", "The 100 m Cliff Edge", "Rocket Delay Cascade", "Fly the Landing"];

export default function App() {
  const [siteId, setSiteId] = useState("shackleton");
  const [custom, setCustom] = useState<P.Site>(() => P.customSite(-85.4, 31.7));
  const [cLat, setCLat] = useState("-85.4");
  const [cLon, setCLon] = useState("31.7");
  const allSites = useMemo(() => [...P.SITES, custom], [custom]);
  const [nudges, setNudges] = useState<Record<string, Cell>>({
    shackleton: { ix: 10, iy: 3 },
    malapert: { ix: 10, iy: 10 },
    mouton: { ix: 10, iy: 10 },
    athena: { ix: 10, iy: 10 },
    chandrayaan3: { ix: 10, iy: 10 },
    apollo11: { ix: 10, iy: 10 },
    custom: { ix: 10, iy: 10 },
  });
  const nowMinute = () => Math.floor(Date.now() / 60000) * 60000;
  const [baseMs, setBaseMs] = useState(nowMinute);
  const [timeMode, setTimeMode] = useState<"now" | "set">("now");
  const setBaseUser = (ms: number) => {
    setTimeMode("set");
    setBaseMs(ms);
  };
  // In NOW mode the simulation follows the real clock, refreshed every 10 minutes.
  useEffect(() => {
    if (timeMode !== "now") return;
    setBaseMs(nowMinute());
    const id = setInterval(() => setBaseMs(nowMinute()), 600000);
    return () => clearInterval(id);
  }, [timeMode]);
  const [delayRaw, setDelayRaw] = useState(0);
  const delay = useDebounced(delayRaw, 20);
  const [mode, setMode] = useState<Mode>("engineer");
  const [tracking, setTracking] = useState<P.Tracking>("vertical");
  const [overlay, setOverlay] = useState<Overlay>("month");
  const [beat, setBeat] = useState<number | null>(null);
  const [crisis, setCrisis] = useState<Crisis | null>(null);
  const [showProv, setShowProv] = useState(false);
  const [briefing, setBriefing] = useState(true);
  const [appMode, setAppMode] = useState<"planner" | "game">("planner");
  const [pins, setPins] = useState<Pin[]>([]);
  const [copied, setCopied] = useState(false);
  const [briefCopied, setBriefCopied] = useState(false);
  const [feed, setFeed] = useState<"checking" | "live" | "local">("checking");
  const [ephV, setEphV] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [, setTick] = useState(0);
  const timers = useRef<any[]>([]);

  const clearTimers = useCallback(() => {
    timers.current.forEach((t) => {
      clearTimeout(t);
      clearInterval(t);
    });
    timers.current = [];
    setPlaying(false);
  }, []);
  useEffect(() => clearTimers, [clearTimers]);

  /* Live ephemeris: try JPL Horizons for the 31 days after the chosen date; fall back to the local engine. */
  useEffect(() => {
    let dead = false;
    const ctl = new AbortController();
    const to = setTimeout(() => ctl.abort(), 7000);
    setFeed("checking");
    (async () => {
      let table: P.EphemerisTable | null = null;
      try {
        const r = await fetch(P.horizonsUrl(baseMs, 31), { signal: ctl.signal });
        if (r.ok) table = P.parseHorizons(await r.text(), baseMs);
      } catch {
        table = null;
      }
      clearTimeout(to);
      if (dead) return;
      P.setEphemerisTable(table);
      setFeed(table ? "live" : "local");
      setEphV((v) => v + 1);
    })();
    return () => {
      dead = true;
      clearTimeout(to);
      ctl.abort();
    };
  }, [baseMs]);

  const site = useMemo(() => allSites.find((s) => s.id === siteId) || allSites[0], [siteId, allSites]);
  const cell = nudges[siteId];
  const running = crisis?.phase === "running";

  const power = useMemo<P.PowerConfig>(
    () => ({
      ...P.DEFAULT_POWER,
      tracking: crisis ? "vertical" : tracking,
      arrayHealth: crisis ? crisis.sc.health : 1,
      loadW: crisis ? crisis.sc.load : P.DEFAULT_POWER.loadW,
    }),
    [tracking, crisis?.sc]
  );

  const tNow = baseMs + delay * DAY;
  const Z = useMemo(() => P.buildElevationMatrix(site), [site]);
  const profile = useMemo(() => P.horizonProfile(site, cell.ix, cell.iy), [site, cell.ix, cell.iy]);
  const timeline = useMemo(() => P.simulateTimeline(site, profile, power, baseMs), [site, profile, power, baseMs, ephV]);
  const now = useMemo(() => P.stateAt(site, profile, power, tNow), [site, profile, power, tNow, ephV]);
  const sunEvt = useMemo(() => P.nextEvent(site, profile, tNow, "sun"), [site, profile, tNow, ephV]);
  const earthEvt = useMemo(() => P.nextEvent(site, profile, tNow, "earth"), [site, profile, tNow, ephV]);
  const grid = useMemo(() => P.surveyGrid(site, power, tNow), [site, power, tNow, ephV]);
  const month = useMemo(() => P.surveyIllumination(site, baseMs), [site, baseMs, ephV]);
  const compare = useMemo(
    () => allSites.map((s) => P.simulateTimeline(s, P.horizonProfile(s, nudges[s.id].ix, nudges[s.id].iy), power, baseMs, 720, 2).stats),
    [allSites, nudges, power, baseMs, ephV]
  );

  const idx = P.clamp(Math.round((delay * 24) / timeline.stepH), 0, timeline.samples.length - 1);
  const soc = timeline.samples[idx].soc;
  const socPct = Math.round(soc * 100);
  const discharging = now.powerW < power.loadW && soc < 1;

  const req = useMemo<P.Requirement>(() => ({ minPowerW: power.loadW, minClearance: now.earthRadius }), [power.loadW, now.earthRadius]);
  const cellI = cell.iy * P.GRID_N + cell.ix;
  const win = useMemo(() => (crisis ? P.surveyWindow(site, tNow) : null), [crisis?.startedAt, site, tNow, ephV]);
  const cellOk = win ? isSafe(win, cellI) : P.meets(grid[cellI], req);
  const safeMask = useMemo(() => (win ? Uint8Array.from({ length: P.GRID_N * P.GRID_N }, (_, i) => (isSafe(win, i) ? 1 : 0)) : null), [win]);
  const haven = useMemo(() => {
    if (cellOk) return null;
    if (win) {
      const h = nearestSafe(win, cell.ix, cell.iy);
      return h ? { ...h, kind: "14-day safe" } : null;
    }
    const both = P.nearestHaven(grid, cell.ix, cell.iy, req);
    if (both) return { ...both, kind: "Sun + Earth" };
    if (grid[cellI].powerW >= req.minPowerW) return null;
    const sunOnly = P.nearestHaven(grid, cell.ix, cell.iy, { minPowerW: req.minPowerW, minClearance: -99 });
    return sunOnly ? { ...sunOnly, kind: "Sun only" } : null;
  }, [grid, cell.ix, cell.iy, cellI, req, cellOk, win]);

  /* ---- actions ---- */
  const moveTo = useCallback(
    (c: Cell) => {
      if ((crisis && crisis.phase !== "running") || !site.terrain) return;
      if (crisis) {
        const cost = Math.abs(c.ix - cell.ix) + Math.abs(c.iy - cell.iy);
        if (cost === 0 || cost > crisis.fuel) return;
        setCrisis({ ...crisis, fuel: crisis.fuel - cost });
      } else clearTimers();
      setNudges((n) => ({ ...n, [siteId]: c }));
    },
    [siteId, site.terrain, crisis, cell.ix, cell.iy, clearTimers]
  );
  const step = (dx: number, dy: number) => moveTo({ ix: P.clamp(cell.ix + dx, 0, 20), iy: P.clamp(cell.iy + dy, 0, 20) });

  const pickSite = (id: string) => {
    if (crisis) return;
    clearTimers();
    setBeat(null);
    setSiteId(id);
  };
  const setDelayUser = (d: number) => {
    if (running) return;
    clearTimers();
    setDelayRaw(d);
  };

  const startCrisis = useCallback(() => {
    clearTimers();
    const c = generateCrisis(site, baseMs);
    if (!c) return;
    setSiteId(c.site.id);
    setNudges((n) => ({ ...n, [c.site.id]: c.start }));
    setDelayRaw(c.delay);
    setOverlay("sun");
    setCrisis({ phase: "running", sc: c.sc, startedAt: performance.now() + 400, elapsed: 0, fuel: FUEL_MAX });
  }, [site, baseMs, clearTimers]);

  const runBeat = (n: number) => {
    clearTimers();
    setBeat(n);
    if (n === 4) {
      setCrisis(null);
      setBeat(null);
      setAppMode("game");
      return;
    }
    setCrisis(null);
    setTracking("vertical");
    if (n === 1) {
      setSiteId("shackleton");
      setBaseUser(Date.parse("2027-05-06T00:00:00Z"));
      setDelayRaw(0);
      setNudges((s) => ({ ...s, shackleton: { ix: 10, iy: 3 } }));
      setOverlay("month");
    } else if (n === 2) {
      setSiteId("shackleton");
      setBaseUser(Date.parse("2027-02-14T00:00:00Z"));
      setDelayRaw(0);
      setNudges((s) => ({ ...s, shackleton: { ix: 12, iy: 2 } }));
      setOverlay("sun");
      timers.current.push(setTimeout(() => setNudges((s) => ({ ...s, shackleton: { ix: 11, iy: 2 } })), 2200));
      timers.current.push(setTimeout(() => setNudges((s) => ({ ...s, shackleton: { ix: 10, iy: 2 } })), 3400));
    } else if (n === 3) {
      setSiteId("mouton");
      setBaseUser(Date.parse("2027-02-16T00:00:00Z"));
      setDelayRaw(0);
      setNudges((s) => ({ ...s, mouton: { ix: 10, iy: 10 } }));
      setOverlay("earth");
      timers.current.push(
        setTimeout(() => {
          let d = 0;
          const id = setInterval(() => {
            d = Math.min(14, d + 0.2);
            setDelayRaw(Math.round(d * 10) / 10);
            if (d >= 14) clearInterval(id);
          }, 55);
          timers.current.push(id);
        }, 1600)
      );
    }
  };

  const play = () => {
    if (playing) {
      clearTimers();
      return;
    }
    clearTimers();
    setPlaying(true);
    let d = delayRaw >= 29.9 ? 0 : delayRaw;
    const id = setInterval(() => {
      d = Math.min(30, d + 0.1);
      setDelayRaw(Math.round(d * 10) / 10);
      if (d >= 30) {
        clearInterval(id);
        setPlaying(false);
      }
    }, 45);
    timers.current.push(id);
  };

  /* ---- crisis clock ---- */
  useEffect(() => {
    if (!running) return;
    const id = setInterval(() => setTick((t) => t + 1), 100);
    return () => clearInterval(id);
  }, [running]);
  const elapsed = crisis ? (running ? Math.max(0, (performance.now() - crisis.startedAt) / 1000) : crisis.elapsed) : 0;
  useEffect(() => {
    if (!crisis || crisis.phase !== "running") return;
    if (delay !== delayRaw) return; // wait for the debounced clock to settle on the crisis instant
    if (!win || elapsed <= 0) return;
    if (cellOk) setCrisis({ ...crisis, phase: "saved", elapsed });
    else if (crisis.fuel <= 0) setCrisis({ ...crisis, phase: "lost", elapsed, why: "fuel" });
    else if (elapsed >= 15) setCrisis({ ...crisis, phase: "lost", elapsed: 15, why: "time" });
  });
  const eclH = win ? win.maxEclipseH[cellI] : 0;
  const losPct = win ? win.earthPct[cellI] : 0;
  const score = crisis ? (crisis.fuel / FUEL_MAX) * 50 + P.clamp((losPct - MIN_EARTH_PCT) / 15, 0, 1) * 25 + P.clamp(1 - eclH / MAX_ECLIPSE_H, 0, 1) * 25 : 0;
  const grade = crisis?.phase === "lost" ? "F" : score >= 65 ? "A" : score >= 45 ? "B" : "C";

  /* ---- derived labels ---- */
  const sunState = now.sunFrac > 0.98 ? "SUNLIT" : now.sunFrac > 0.02 ? "PARTIAL ECLIPSE" : "ECLIPSED";
  const sunTone = now.sunFrac > 0.98 ? "amber" : now.sunFrac > 0.02 ? "orange" : "slate";
  const lockLabel = now.lock === "LOCK" ? "NOMINAL LOCK" : now.lock === "GRAZING" ? "GRAZING LOCK" : "RIDGE OCCULTATION BLACKOUT";
  const lockTone = now.lock === "LOCK" ? "cyan" : now.lock === "GRAZING" ? "blue" : "crimson";
  const st = timeline.stats;
  const slope = useMemo(() => P.surveySlope(site), [site]);
  const slopeHere = slope.max[cell.iy * P.GRID_N + cell.ix];
  const slopeMean = slope.mean[cell.iy * P.GRID_N + cell.ix];
  const roughHere = slope.rough[cell.iy * P.GRID_N + cell.ix];
  const surface = !site.terrain ? "NO DATA" : slopeHere <= P.SLOPE_SAFE_DEG ? "FLAT · SAFE" : slopeHere <= P.SLOPE_LIMIT_DEG ? "SLOPED · CAUTION" : "STEEP · HAZARD";
  const surfaceTone = !site.terrain ? "dim" : slopeHere <= P.SLOPE_SAFE_DEG ? "green" : slopeHere <= P.SLOPE_LIMIT_DEG ? "amber" : "crimson";
  const scanStart = Math.floor(baseMs / DAY) * DAY;
  const scan = useMemo(() => P.scanYear(site, profile, scanStart), [site, profile, scanStart, ephV]);
  const ephNow = useMemo(() => P.ephemeris(tNow), [tNow, ephV]);
  const canDownload = typeof location !== "undefined" && (location.protocol === "file:" || /github\.io$/.test(location.hostname));
  const pickDate = (ms: number) => {
    if (crisis) return;
    clearTimers();
    setBeat(null);
    setBaseUser(ms);
    setDelayRaw(0);
  };
  const findBest = () => {
    if (crisis || !site.terrain) return;
    const w = P.surveyWindow(site, baseMs, 720);
    let bi = 0;
    let bs = -1;
    for (let i = 0; i < month.length; i++) {
      // Flat ground first: cells steeper than the safe limit are heavily penalised, hazards excluded.
      if (slope.max[i] > P.SLOPE_LIMIT_DEG) continue;
      const sc = month[i] + w.earthPct[i] - Math.max(0, w.maxEclipseH[i] - 24) * 0.3 - Math.max(0, slope.max[i] - P.SLOPE_SAFE_DEG) * 12;
      if (sc > bs) {
        bs = sc;
        bi = i;
      }
    }
    moveTo({ ix: bi % P.GRID_N, iy: Math.floor(bi / P.GRID_N) });
  };
  const pinNow = () =>
    setPins((p) => [
      ...p.slice(-4),
      { id: Date.now(), label: `${site.short} · ${sgn(dE, 0)} E ${sgn(dN, 0)} N · ${fmtDay(baseMs + delayRaw * DAY)}`, siteId, cell, baseMs, delay: delayRaw, stats: st, slope: slopeHere },
    ]);
  const restore = (p: Pin) => {
    if (crisis) return;
    clearTimers();
    setBeat(null);
    if (p.siteId === "custom" && siteId !== "custom") return;
    setSiteId(p.siteId);
    setNudges((n) => ({ ...n, [p.siteId]: p.cell }));
    setBaseUser(p.baseMs);
    setDelayRaw(p.delay);
  };
  const copyBrief = () => {
    const best = P.bestWindows(scan);
    const lines = [
      "LUNAR LANDING SITE BRIEF",
      `Site: ${site.name} (${Math.abs(site.lat).toFixed(4)}°${site.lat < 0 ? "S" : "N"}, ${site.lon.toFixed(4)}°E)`,
      `Lander position: ${sgn(dE, 0)} m east, ${sgn(dN, 0)} m north of site centre; elevation ${sgn(Z[cell.iy][cell.ix], 0)} m`,
      `Epoch: ${fmtDate(tNow)} UTC (${P.seasonLabel(ephNow.subSolarLat)})`,
      "",
      "AT EPOCH",
      `Sun: elevation ${sgn(now.sunEl)}°, azimuth ${now.sunAz.toFixed(1)}°, ${sunState}; ${sunEvt.active ? "sunset" : "sunrise"} in ${sunEvt.hours === null ? "30 d+" : fmtDur(sunEvt.hours)}`,
      `Array power: ${now.powerW.toFixed(0)} W against ${power.loadW} W load`,
      `Earth: ${sgn(now.earthClearance, 1)}° over terrain, ${lockLabel}; ${earthEvt.active ? "Earthset" : "Earthrise"} in ${earthEvt.hours === null ? "30 d+" : fmtDur(earthEvt.hours)}`,
      "",
      "NEXT 30 DAYS",
      `Sunlit ${st.sunPct.toFixed(0)}%, longest night ${st.longestNightH} h`,
      `Earth link ${st.commsPct.toFixed(0)}%, longest blackout ${fmtDur(st.longestBlackoutH)}`,
      `Battery low point ${(st.minSoc * 100).toFixed(0)}%`,
      "",
      "LANDING SURFACE",
      site.terrain ? `${surface}: max slope ${slopeHere.toFixed(1)}°, mean ${slopeMean.toFixed(1)}°, roughness ${roughHere.toFixed(1)} m (20 m baseline)` : "No terrain loaded",
      "",
      "BEST 14-DAY LANDING WINDOWS, NEXT 12 MONTHS",
      ...best.map((d, i) => `${i + 1}. ${fmtDay(scanStart + d * DAY)}: Sun ${scan.sunPct[d].toFixed(0)}%, Earth ${scan.earthPct[d].toFixed(0)}%, longest eclipse ${scan.nightH[d].toFixed(0)} h`),
      "",
      `Sources: ${feed === "live" ? "JPL Horizons live feed" : "analytic ephemeris (within 0.06° of JPL Horizons)"}; NASA LRO LOLA LDEM_80S_20M and LDEM_75S_240M.`,
      "Lander power and link figures are illustrative assumptions.",
    ];
    try {
      navigator.clipboard.writeText(lines.join("\n")).then(
        () => {
          setBriefCopied(true);
          setTimeout(() => setBriefCopied(false), 1600);
        },
        () => {}
      );
    } catch {}
  };
  const copyCsv = () => {
    try {
      navigator.clipboard.writeText(P.timelineCsv(site, timeline)).then(
        () => {
          setCopied(true);
          setTimeout(() => setCopied(false), 1600);
        },
        () => {}
      );
    } catch {}
  };
  const downloadCsv = () => {
    try {
      const a = document.createElement("a");
      a.href = URL.createObjectURL(new Blob([P.timelineCsv(site, timeline)], { type: "text/csv" }));
      a.download = `${site.id}_${new Date(baseMs).toISOString().slice(0, 10)}_timeline.csv`;
      a.click();
    } catch {}
  };
  const dE = (cell.ix - 10) * 100;
  const dN = (cell.iy - 10) * 100;
  const monthHere = month[cell.iy * P.GRID_N + cell.ix];
  const explorer = mode === "explorer";
  const socClass = socPct < 20 ? "flash-crimson" : discharging && socPct < 50 ? "flash-orange" : "";

  let caption: React.ReactNode = null;
  if (beat === 1)
    caption = (
      <>
        This is the sunniest cell of this 2 km patch in south-polar winter, on a ridge often called a peak of eternal
        light. On real LOLA terrain, over the next 30 days the Sun is blocked <b>{(100 - st.sunPct).toFixed(0)}%</b> of the time, the longest night lasts{" "}
        <b>{st.longestNightH} h</b>, and the battery {st.minSoc <= 0.001 ? <b>runs flat</b> : <>bottoms out at <b>{(st.minSoc * 100).toFixed(0)}%</b></>}.
        Distant peaks on the horizon are enough to eclipse a Sun that never climbs above 2°.
      </>
    );
  else if (beat === 2)
    caption = (
      <>
        Same ridge, same hour, 200 m apart. The lander at ΔE {sgn(dE, 0)} m is <b>{sunState}</b> with{" "}
        <b>{monthHere.toFixed(0)}%</b> sunlight over the next 30 days. Watch it step west onto the crest: permanent
        shadow becomes mostly Sun without changing the landing date.
      </>
    );
  else if (beat === 3)
    caption = (
      <>
        Planned landing {fmtDay(baseMs)}: Earth sits high over the ridge. Slip the launch and libration carries it down
        behind the terrain to the north-west. At <b>+{delayRaw.toFixed(1)}&nbsp;d</b> the link is <b>{lockLabel}</b> with Earth{" "}
        <b>{now.earthClearance >= 0 ? sgn(now.earthClearance, 1) + "° above" : Math.abs(now.earthClearance).toFixed(1) + "° below"}</b>{" "}
        the ridge, and the Sun is <b>{sunState}</b>.
      </>
    );
  else if (beat === 4)
    caption = (
      <>
        A random failure, 15 seconds and fuel for 5 nudges of 100 m. Reach a cell that, over the next 14 days, never
        sits in eclipse for 48 hours straight and keeps Earth in view more than 85% of the time. Follow the pulsing
        gold arrow.
      </>
    );

  return (
    <div className="app">
      <Starfield />
      <header className="top">
        <div className="brand">
          <div className="brand-mark" aria-hidden="true" />
          <div>
            <h1>Lunar Landing Site Navigator</h1>
            <p>South pole · Sun and Earth above the horizon, by site and date</p>
          </div>
        </div>
        <div className="clock">
          <div>
            {timeMode === "now" && delay === 0 ? "LIVE UTC" : "SIM UTC"} <b>{fmtDate(tNow)}</b>
          </div>
          <div>
            {P.seasonLabel(now ? P.ephemeris(tNow).subSolarLat : 0)} · T+{delay.toFixed(1)} d
          </div>
        </div>
        <div className="timectl">
          <div className="seg" role="group" aria-label="Simulation time">
            <button
              aria-pressed={timeMode === "now"}
              disabled={!!crisis}
              onClick={() => {
                clearTimers();
                setBeat(null);
                setDelayRaw(0);
                setTimeMode("now");
              }}
            >
              Now
            </button>
            <button aria-pressed={timeMode === "set"} disabled={!!crisis} onClick={() => setTimeMode("set")}>
              Set time
            </button>
          </div>
          {timeMode === "set" && (
            <input
              id="sim-time"
              type="datetime-local"
              aria-label="Simulation start time, UTC"
              value={new Date(baseMs).toISOString().slice(0, 16)}
              min="2020-01-01T00:00"
              max="2045-12-31T23:59"
              disabled={!!crisis}
              onChange={(e) => {
                const t = Date.parse(e.target.value + ":00Z");
                if (!isNaN(t)) {
                  clearTimers();
                  setBeat(null);
                  setBaseUser(t);
                }
              }}
            />
          )}
        </div>
        <div className={"feed " + feed} title={feed === "live" ? "Sun and Earth positions from JPL Horizons" : "Sun and Earth positions from the built-in ephemeris engine"}>
          <i />
          {feed === "live" ? "DATA: LIVE FEED" : feed === "local" ? "DATA: LOCAL CACHE" : "DATA: CONTACTING JPL"}
        </div>
        <div className="seg modeseg" role="group" aria-label="Section">
          <button aria-pressed={appMode === "planner"} onClick={() => setAppMode("planner")}>
            Mission Planner
          </button>
          <button
            aria-pressed={appMode === "game"}
            onClick={() => {
              clearTimers();
              setCrisis(null);
              setAppMode("game");
            }}
          >
            ▶ Lander Game
          </button>
        </div>
        <div className="seg" role="group" aria-label="Audience mode" style={appMode === "game" ? { display: "none" } : undefined}>
          <button aria-pressed={mode === "engineer"} onClick={() => setMode("engineer")}>
            Flight Engineer
          </button>
          <button aria-pressed={mode === "explorer"} onClick={() => setMode("explorer")}>
            Explorer
          </button>
        </div>
        <button className="btn" onClick={() => setShowProv(true)}>
          Data &amp; Agency Provenance
        </button>
      </header>

      {appMode === "game" && (
        <section className="panel game">
          <div className="panel-head">
            <h2>Landing simulator · {site.terrain ? site.name : "Shackleton Connecting Ridge"}</h2>
            <span className="tag">LOLA terrain cross-section · lunar gravity 1.62 m/s²</span>
          </div>
          <div className="game-grid">
            <LanderGame
              site={site.terrain ? site : P.SITES[0]}
              rowIy={site.terrain ? cell.iy : 10}
              grid={site.terrain ? grid : P.surveyGrid(P.SITES[0], power, tNow)}
              sunAz={now.sunAz}
              sunLit={now.sunFrac > 0.02}
              earthVisible={now.lock !== "BLACKOUT"}
            />
            <aside className="game-side">
              <div>
                <h3>Your mission</h3>
                <p>
                  Bring the lander down on real terrain: an east-west slice through the planner's current lander row.
                  Green ground is flat enough to land on, amber is risky, red will tip you over.
                </p>
              </div>
              <div>
                <h3>Touchdown limits</h3>
                <ul>
                  <li>Descent under {LIMITS.vVert} m/s</li>
                  <li>Sideways drift under {LIMITS.vHoriz} m/s</li>
                  <li>Tilt under {LIMITS.tilt}°</li>
                  <li>Ground slope under {LIMITS.slope}°</li>
                </ul>
              </div>
              <div>
                <h3>Scoring</h3>
                <p>Fuel left, a soft touchdown and flat ground raise your grade. So does landing where the planner says there is sunlight and a view of Earth right now.</p>
              </div>
              <div>
                <h3>Landing site</h3>
                <div className="sites">
                  {P.SITES.filter((s) => s.terrain).map((s) => (
                    <button key={s.id} className="site" aria-pressed={s.id === siteId} onClick={() => setSiteId(s.id)}>
                      <span className="nm">{s.name}</span>
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <h3>Second challenge · site triage</h3>
                <p>A failure strikes. You get 15 seconds and 5 moves on the planner map to reach a highlighted safe cell.</p>
                <button
                  className="btn"
                  onClick={() => {
                    setAppMode("planner");
                    setBeat(null);
                    startCrisis();
                  }}
                >
                  Start site triage
                </button>
              </div>
            </aside>
          </div>
        </section>
      )}

      <nav className="tour" aria-label="Guided tour" style={appMode === "game" ? { display: "none" } : undefined}>
        <div className="tour-head">
          <span className="tour-title">Judge's 60-Second Guided Tour</span>
          <div className="beats">
            {BEATS.map((b, i) => (
              <button key={b} className="beat" aria-pressed={beat === i + 1} onClick={() => runBeat(i + 1)}>
                <span className="n">{i + 1}</span>
                <span className="t">{b}</span>
              </button>
            ))}
          </div>
        </div>
        {caption && <p className="tour-caption">{caption}</p>}
      </nav>

      {crisis && (
        <div className={"crisis" + (crisis.phase === "saved" ? " saved" : "")} role="status" aria-live="polite">
          <div className={"count" + (crisis.phase === "lost" ? " pulse-crit" : "")}>
            {crisis.phase === "running" ? Math.max(0, 15 - elapsed).toFixed(1) : grade}
          </div>
          <div>
            <h2 className={crisis.phase === "lost" ? "pulse-crit" : ""}>
              {crisis.phase === "running"
                ? "Crisis: " + crisis.sc.title
                : crisis.phase === "saved"
                ? `Mission saved in ${elapsed.toFixed(1)} s · grade ${grade}`
                : "LOSS OF VEHICLE"}
            </h2>
            <p>
              {crisis.phase === "lost"
                ? (crisis.why === "fuel" ? "Hover fuel exhausted" : "Time ran out") + " before reaching a safe cell. The gold arrow shows the nearest one."
                : crisis.sc.detail + " Move to a green cell on the map: click it or use the arrow pad. Each 100 m costs one fuel."}
            </p>
          </div>
          <div className="checks">
            <span className={eclH < MAX_ECLIPSE_H ? "ok" : "bad"}>
              {eclH < MAX_ECLIPSE_H ? "✓" : "✗"} LONGEST ECLIPSE {eclH.toFixed(0)} h / need &lt; {MAX_ECLIPSE_H} h
            </span>
            <span className={losPct > MIN_EARTH_PCT ? "ok" : "bad"}>
              {losPct > MIN_EARTH_PCT ? "✓" : "✗"} EARTH IN VIEW {losPct.toFixed(0)}% / need &gt; {MIN_EARTH_PCT}%
            </span>
            <span className={crisis.fuel > 1 ? "" : "bad"}>
              HOVER FUEL {"●".repeat(crisis.fuel)}{"○".repeat(FUEL_MAX - crisis.fuel)}
            </span>
          </div>
          <div className="actions">
            {crisis.phase !== "running" && (
              <button className="btn primary" onClick={startCrisis}>
                New failure
              </button>
            )}
            <button
              className="btn"
              onClick={() => {
                setCrisis(null);
                setBeat(null);
              }}
            >
              Exit triage
            </button>
          </div>
        </div>
      )}

      <main className="grid" style={appMode === "game" ? { display: "none" } : undefined}>
        {/* ---------------- left ---------------- */}
        <div className="col">
          <Panel title="Micro-terrain nudge map" tag={site.terrain ? "LOLA 20 m DEM" : "No terrain"}>
            <NudgeMap
              site={site}
              cell={cell}
              grid={grid}
              month={month}
              overlay={overlay}
              haven={haven}
              pulse={!!crisis}
              safe={safeMask}
              slope={slope}
              sunAz={now.sunAz}
              sunLit={now.sunFrac > 0.02}
              onMove={moveTo}
            />
            <div className="map-tools">
              <div className="dpad" role="group" aria-label="Move lander 100 metres">
                <span />
                <button onClick={() => step(0, 1)} aria-label="North 100 m">▲</button>
                <span />
                <button onClick={() => step(-1, 0)} aria-label="West 100 m">◀</button>
                <button onClick={() => moveTo({ ix: 10, iy: 10 })} aria-label="Back to grid centre">●</button>
                <button onClick={() => step(1, 0)} aria-label="East 100 m">▶</button>
                <span />
                <button onClick={() => step(0, -1)} aria-label="South 100 m">▼</button>
                <span />
              </div>
              <dl className="readout">
                <dt>ΔEast</dt>
                <dd>{sgn(dE, 0)} m</dd>
                <dt>ΔNorth</dt>
                <dd>{sgn(dN, 0)} m</dd>
                <dt>Elevation</dt>
                <dd>{sgn(Z[cell.iy][cell.ix], 0)} m</dd>
                <dt>Slope (max)</dt>
                <dd className={surfaceTone}>{site.terrain ? slopeHere.toFixed(1) + "°" : "n/a"}</dd>
                <dt>30-d Sun</dt>
                <dd>{monthHere.toFixed(0)}%</dd>
              </dl>
              <button className="btn small glow" onClick={findBest} disabled={!!crisis || !site.terrain}>
                ◎ Find best cell
              </button>
              <label className="field">
                Overlay
                <select id="overlay" value={overlay} onChange={(e) => setOverlay(e.target.value as Overlay)}>
                  <option value="sun">Sunlight now</option>
                  <option value="earth">Earth link now</option>
                  <option value="month">30-day sunlight %</option>
                  <option value="slope">Slope hazard</option>
                  <option value="none">Terrain only</option>
                </select>
              </label>
            </div>
            <div className={"surface " + surfaceTone}>
              <span className="k">Landing surface</span>
              <b>{surface}</b>
              {site.terrain && (
                <span className="mono">
                  max {slopeHere.toFixed(1)}° · mean {slopeMean.toFixed(1)}° · roughness {roughHere.toFixed(1)} m
                </span>
              )}
            </div>
            <div className="legend">
              {overlay === "sun" && (
                <>
                  <span><i style={{ background: C.amber }} />Sunlit</span>
                  <span><i style={{ background: "#04060e", border: "1px solid #334155" }} />In shadow</span>
                </>
              )}
              {overlay === "earth" && (
                <>
                  <span><i style={{ background: C.cyan }} />Nominal lock</span>
                  <span><i style={{ background: C.blue }} />Grazing</span>
                  <span><i style={{ background: C.crimson }} />Blackout</span>
                </>
              )}
              {overlay === "slope" && (
                <>
                  <span><i style={{ background: GREEN }} />≤ {P.SLOPE_SAFE_DEG}° flat</span>
                  <span><i style={{ background: C.amber }} />{P.SLOPE_SAFE_DEG}–{P.SLOPE_LIMIT_DEG}° caution</span>
                  <span><i style={{ background: C.crimson }} />&gt; {P.SLOPE_LIMIT_DEG}° hazard</span>
                </>
              )}
              {overlay === "month" && (
                <>
                  <span><i style={{ background: C.amber }} />More sunlit hours</span>
                  <span><i style={{ background: "#04060e", border: "1px solid #334155" }} />Fewer</span>
                </>
              )}
              {haven && (
                <span className="gold">
                  → Best safe haven ({haven.kind}): {haven.dist.toFixed(0)} m
                </span>
              )}
              <span>2.1 km × 2.1 km · 100 m cells · 10 m contours</span>
            </div>
            {explorer && (
              <p className="callout">
                This is real laser-altimeter terrain. Each square is 100 m. The Sun skims the horizon here, so a ridge only <b>20 m</b> tall casts a shadow
                half a kilometre long. Moving one or two squares can trade weeks of darkness for weeks of light.
              </p>
            )}
          </Panel>

          <Panel title="Sites · next 30 days" tag="Compare">
            <div className="sites">
              {allSites.map((s, i) => (
                <React.Fragment key={s.id}>
                  {i === 0 && <div className="grp-label">South pole · LOLA terrain</div>}
                  {i === 4 && <div className="grp-label">Reference sites · smooth sphere</div>}
                  <button className="site" aria-pressed={s.id === siteId} onClick={() => pickSite(s.id)} disabled={!!crisis}>
                    <span className="nm">{s.name}</span>
                    <span className="co">
                      {Math.abs(s.lat).toFixed(2)}°{s.lat < 0 ? "S" : "N"} {s.lon.toFixed(1)}°E
                    </span>
                    <span className="bars">
                      <span>Sun</span>
                      <span className="bar">
                        <i style={{ width: compare[i].sunPct + "%", background: C.amber }} />
                      </span>
                      <span className="v">{compare[i].sunPct.toFixed(0)}%</span>
                      <span>Earth</span>
                      <span className="bar">
                        <i style={{ width: compare[i].commsPct + "%", background: C.cyan }} />
                      </span>
                      <span className="v">{compare[i].commsPct.toFixed(0)}%</span>
                      <span>Longest night</span>
                      <span />
                      <span className="v">{compare[i].longestNightH} h</span>
                    </span>
                  </button>
                </React.Fragment>
              ))}
              <form
                className="custom"
                onSubmit={(e) => {
                  e.preventDefault();
                  const la = parseFloat(cLat);
                  const lo = parseFloat(cLon);
                  if (isNaN(la) || isNaN(lo) || crisis) return;
                  clearTimers();
                  setBeat(null);
                  setCustom(P.customSite(la, lo));
                  setSiteId("custom");
                }}
              >
                <label className="field">
                  Latitude °N
                  <input id="c-lat" type="number" step="any" min={-90} max={90} value={cLat} onChange={(e) => setCLat(e.target.value)} />
                </label>
                <label className="field">
                  Longitude °E
                  <input id="c-lon" type="number" step="any" min={-360} max={360} value={cLon} onChange={(e) => setCLon(e.target.value)} />
                </label>
                <button className="btn small" type="submit" disabled={!!crisis}>
                  Evaluate
                </button>
              </form>
            </div>
            {site.id === "athena" && (
              <p className="callout">
                <b>Hindcast.</b> {site.note} Load the landing time to see what this tool reports for that moment. The
                crater that caught the lander is smaller than the 20 m terrain data can show, which is the limit of
                any map-based check.{" "}
                <button className="lnk" onClick={() => pickDate(Date.parse("2025-03-06T17:30:00Z"))}>
                  Load 6 Mar 2025, about 17:30 UTC
                </button>
              </p>
            )}
            {explorer && <p className="callout">{site.note} Bars compare every site at its current lander position.</p>}
          </Panel>
        </div>

        {/* ---------------- middle ---------------- */}
        <div className="col">
          <div className="tiles">
            <div className={"tile s-" + sunTone}>
              <span className="k">Sun</span>
              <span className={"pill " + (sunTone === "slate" ? "dim" : sunTone)}>{sunState}</span>
              <span className="big">
                {sgn(now.sunEl, 2)}°<small>elevation</small>
              </span>
              <span className="sub">
                {sunEvt.active ? "Sunset in " : "Sunrise in "}
                <b>{sunEvt.hours === null ? "30 d+" : fmtDur(sunEvt.hours)}</b>
              </span>
            </div>
            <div className={"tile s-" + (now.powerW >= power.loadW ? "amber" : "crimson")}>
              <span className="k">Array power</span>
              <span className="big">
                {now.powerW.toFixed(0)}
                <small>W</small>
              </span>
              <span className="sub">
                Load {power.loadW} W · net <b className={now.powerW >= power.loadW ? "" : "crimson"}>{sgn(now.powerW - power.loadW, 0)} W</b>
              </span>
              <span className="sub">
                {explorer ? `${(now.sunFrac * 100).toFixed(0)}% of the Sun's disc is visible` : `Cosine eff. ${(now.cosEff * 100).toFixed(1)}% · disc ${(now.sunFrac * 100).toFixed(0)}%`}
              </span>
            </div>
            <div className={"tile s-" + (socPct < 20 ? "crimson" : socPct < 50 ? "orange" : "cyan")}>
              <span className="k">Battery state of charge</span>
              <span className={"big " + socClass}>
                <NumberRoll value={socPct} />
                <small>%</small>
              </span>
              <span className="sub">
                {discharging ? "Discharging" : soc >= 1 ? "Full" : "Charging"} · 30-day low <b>{(st.minSoc * 100).toFixed(0)}%</b>
              </span>
            </div>
            <div className={"tile s-" + lockTone}>
              <span className="k">Direct-to-Earth link</span>
              <span className={"pill " + lockTone}>{lockLabel}</span>
              <span className="big">
                {sgn(now.earthClearance, 1)}°<small>clear</small>
              </span>
              <span className="sub">
                {earthEvt.active ? "Earthset in " : "Earthrise in "}
                <b>{earthEvt.hours === null ? "30 d+" : fmtDur(earthEvt.hours)}</b>
                {!explorer && isFinite(now.linkMarginDb) && <> · margin <b>{sgn(now.linkMarginDb, 1)} dB</b></>}
              </span>
            </div>
          </div>

          <Panel title="360° horizon panorama" tag="Vertical scale exaggerated">
            <Panorama profile={profile} timeline={timeline} now={now} />
            <div className="legend">
              <span><i style={{ background: C.gold }} />Sun's path over one lunar day (29.5 d)</span>
              <span><i style={{ background: C.cyan }} />Earth's libration path</span>
              <span><i style={{ background: "#273449" }} />Terrain seen from the lander</span>
            </div>
            {explorer && (
              <p className="callout">
                The Moon's axis is tilted only <b>1.54°</b> (Earth's is 23.4°), so at the pole the Sun never climbs. It
                circles the horizon once every 29.5 days, and any hill along the way can eclipse it. There is no air to
                bend or scatter light: behind a hill it is simply dark and about −200 °C.
              </p>
            )}
          </Panel>

          <Panel
            title="Timeline · launch delay"
            right={
              <span style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                <button className="btn small" onClick={copyCsv}>
                  {copied ? "Copied ✓" : "Copy CSV"}
                </button>
                {canDownload && (
                  <button className="btn small" onClick={downloadCsv}>
                    Download CSV
                  </button>
                )}
                <button className="btn small" onClick={play} disabled={running}>
                  {playing ? "■ Stop" : "▶ Play 30 days"}
                </button>
              </span>
            }
          >
            <div className="controls">
              <label className="field">
                Planned landing (UTC)
                <input
                  id="base-date"
                  type="date"
                  value={new Date(baseMs).toISOString().slice(0, 10)}
                  min="2024-01-01"
                  max="2040-12-31"
                  disabled={!!crisis}
                  onChange={(e) => {
                    const t = Date.parse(e.target.value + "T00:00:00Z");
                    if (!isNaN(t)) {
                      clearTimers();
                      setBeat(null);
                      setBaseUser(t);
                    }
                  }}
                />
              </label>
              <label className="field">
                Solar array
                <select id="tracking" value={power.tracking} disabled={!!crisis} onChange={(e) => setTracking(e.target.value as P.Tracking)}>
                  <option value="vertical">Vertical, Sun-tracking · cos(El)</option>
                  <option value="horizontal">Flat deck · sin(El)</option>
                </select>
              </label>
              <div className="slider-row" style={{ marginLeft: "auto" }}>
                <span className="val">+{delayRaw.toFixed(1)} Days</span>
              </div>
            </div>
            <input
              id="delay"
              type="range"
              min={0}
              max={30}
              step={0.1}
              value={delayRaw}
              disabled={running}
              aria-label="Launch delay in days"
              onChange={(e) => setDelayUser(+e.target.value)}
            />
            <div className="spark-rows">
              <div className="spark-labels">
                <span className="amber">SUN</span>
                <span className="cyan">EARTH</span>
                <span>BATTERY</span>
              </div>
              <Sparkline timeline={timeline} delay={delay} onPick={setDelayUser} />
            </div>
            <div className="axis">
              <span>{fmtDay(baseMs)}</span>
              <span>+10 d</span>
              <span>+20 d</span>
              <span>{fmtDay(baseMs + 30 * DAY)}</span>
            </div>
            <div className="legend">
              <span><i style={{ background: C.amber }} />Sunlit</span>
              <span><i style={{ background: C.slate }} />Eclipse</span>
              <span><i style={{ background: C.cyan }} />Earth lock</span>
              <span><i style={{ background: C.blue }} />Grazing</span>
              <span><i style={{ background: C.crimson }} />Comms blackout / battery flat</span>
            </div>
            <div className="stats">
              <span>Sunlit <b>{st.sunPct.toFixed(0)}%</b></span>
              <span>Longest night <b>{st.longestNightH} h</b></span>
              <span>Earth link <b>{st.commsPct.toFixed(0)}%</b></span>
              <span>Longest blackout <b>{fmtDur(st.longestBlackoutH)}</b></span>
              <span>Mean power <b>{st.meanPowerW.toFixed(0)} W</b></span>
            </div>
            {explorer && (
              <p className="callout">
                Rockets slip. Drag the slider to delay the landing and watch the three stripes: a date that was sunny
                with a clear radio link can turn dark and silent two weeks later, because the Sun has moved halfway
                round the horizon and Earth has wobbled lower.
              </p>
            )}
          </Panel>

          <Panel title="Landing window finder · next 12 months" tag="14-day surface mission">
            <WindowFinder scan={scan} startMs={scanStart} onPick={pickDate} />
            <p className="dim" style={{ margin: 0, fontSize: 12 }}>
              Each column is a landing date at the current lander position. Brighter means more of the following 14 days
              in sunlight (top) or with Earth in view (middle); red marks an eclipse of 48 hours or longer. White boxes
              are the three best windows. Click any date to load it.
            </p>
          </Panel>

          <Panel
            title="Scenario comparison"
            right={
              <span style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                <button className="btn small" onClick={copyBrief}>
                  {briefCopied ? "Copied ✓" : "Copy site brief"}
                </button>
                <button className="btn small glow" onClick={pinNow}>
                  + Pin current scenario
                </button>
              </span>
            }
          >
            <div style={{ overflowX: "auto" }}>
              <table className="cmp">
                <thead>
                  <tr>
                    <th>Scenario (30 days from landing)</th>
                    <th>Sun</th>
                    <th>Longest night</th>
                    <th>Earth link</th>
                    <th>Longest blackout</th>
                    <th>Battery low</th>
                    <th>Slope</th>
                    <th />
                  </tr>
                </thead>
                <tbody>
                  <tr className="cur">
                    <td>Current · {site.short} · {sgn(dE, 0)} E {sgn(dN, 0)} N · {fmtDay(baseMs)}</td>
                    <td>{st.sunPct.toFixed(0)}%</td>
                    <td>{st.longestNightH} h</td>
                    <td>{st.commsPct.toFixed(0)}%</td>
                    <td>{fmtDur(st.longestBlackoutH)}</td>
                    <td>{(st.minSoc * 100).toFixed(0)}%</td>
                    <td>{site.terrain ? slopeHere.toFixed(1) + "°" : "n/a"}</td>
                    <td />
                  </tr>
                  {pins.map((p) => (
                    <tr key={p.id}>
                      <td>
                        <button className="lnk" onClick={() => restore(p)}>{p.label}</button>
                      </td>
                      <td className={p.stats.sunPct > st.sunPct ? "ok" : ""}>{p.stats.sunPct.toFixed(0)}%</td>
                      <td className={p.stats.longestNightH < st.longestNightH ? "ok" : ""}>{p.stats.longestNightH} h</td>
                      <td className={p.stats.commsPct > st.commsPct ? "ok" : ""}>{p.stats.commsPct.toFixed(0)}%</td>
                      <td className={p.stats.longestBlackoutH < st.longestBlackoutH ? "ok" : ""}>{fmtDur(p.stats.longestBlackoutH)}</td>
                      <td className={p.stats.minSoc > st.minSoc ? "ok" : ""}>{(p.stats.minSoc * 100).toFixed(0)}%</td>
                      <td className={p.slope < slopeHere ? "ok" : ""}>{p.slope.toFixed(1)}°</td>
                      <td>
                        <button className="lnk" aria-label="Remove pinned scenario" onClick={() => setPins((x) => x.filter((q) => q.id !== p.id))}>✕</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {pins.length === 0 && (
              <p className="dim" style={{ margin: 0, fontSize: 12 }}>
                Pin a scenario, then change the site, position or date. Pinned rows stay for side-by-side comparison;
                cyan marks where a pinned scenario beats the current one. Click a pinned row to reload it.
              </p>
            )}
          </Panel>
        </div>

        {/* ---------------- right ---------------- */}
        <div className="col col-right">
          <Panel title="Earth libration reticle" tag="True angular scale">
            <EarthReticle profile={profile} timeline={timeline} now={now} />
            {explorer ? (
              <p className="callout">
                The Moon is <b>tidally locked</b>: one face always points at Earth, so Earth never rises or sets. It
                hovers in one patch of sky and traces a slow loop about once a month as the Moon's tilted, oval orbit
                lets us see slightly around its edges (libration). Near the pole Earth sits right on the horizon, so
                that small loop decides whether the radio link works at all.
              </p>
            ) : (
              <div className="legend">
                <span><i style={{ background: C.cyan }} />30-day path, visible</span>
                <span><i style={{ background: C.crimson }} />Occulted by ridge</span>
                <span>Disc {(now.earthRadius * 2).toFixed(2)}°</span>
              </div>
            )}
          </Panel>

          <Panel title="South pole from above" tag="80°S to pole">
            <PolarView eph={ephNow} siteId={siteId} />
            {explorer ? (
              <p className="callout">
                Looking straight down on the pole. The amber half is in daylight; it sweeps around once every 29.5 days.
                Earth always sits toward the top, wobbling slightly. A site needs the Sun's side and Earth's side clear
                of mountains at the same time.
              </p>
            ) : (
              <div className="legend">
                <span><i style={{ background: C.amber }} />Sunlit hemisphere (terminator)</span>
                <span>0° longitude up, 90°E right</span>
              </div>
            )}
          </Panel>

          {explorer ? (
            <Panel title="What am I looking at?">
              <div className="explain">
                <div>
                  <h3>Why land at the south pole?</h3>
                  <p>Craters there never see sunlight and trap water ice. Ridges next to them get sunlight most of the time. Missions want both within driving distance.</p>
                </div>
                <div>
                  <h3>Right now at {site.short}</h3>
                  <p>
                    The Sun is <b>{Math.abs(now.sunEl).toFixed(1)}° {now.sunEl >= 0 ? "above" : "below"}</b> a flat horizon and the terrain in that direction rises to <b>{sgn(now.sunHorizon, 1)}°</b>, so the lander is{" "}
                    <b>{sunState.toLowerCase()}</b>. Earth is <b>{now.earthClearance >= 0 ? "visible" : "hidden"}</b>,{" "}
                    {Math.round(now.earthRangeKm).toLocaleString("en-US")} km away.
                  </p>
                </div>
                <div>
                  <h3>How this differs from Earth</h3>
                  <p>One lunar day lasts 29.5 Earth days. A polar lander that loses the Sun may wait days for it to return, on battery alone, with no atmosphere to hold any warmth.</p>
                </div>
              </div>
            </Panel>
          ) : (
            <Panel title="Flight telemetry">
              <dl className="tele">
                <div className="grp">Solar</div>
                <dt>Sun azimuth / elevation</dt>
                <dd>{now.sunAz.toFixed(2)}° / {sgn(now.sunEl)}°</dd>
                <dt>Terrain horizon at Sun azimuth</dt>
                <dd>{sgn(now.sunHorizon)}°</dd>
                <dt>Solar disc visible</dt>
                <dd>{(now.sunFrac * 100).toFixed(1)}%</dd>
                <dt>Cosine efficiency</dt>
                <dd>{(now.cosEff * 100).toFixed(2)}%</dd>
                <dt>Array output / load</dt>
                <dd>{now.powerW.toFixed(0)} W / {power.loadW} W</dd>
                <dt>Sub-solar lat / lon</dt>
                <dd>{sgn(P.ephemeris(tNow).subSolarLat)}° / {sgn(P.ephemeris(tNow).subSolarLon, 1)}°</dd>
                <div className="grp">Direct-to-Earth</div>
                <dt>Earth azimuth / elevation</dt>
                <dd>{now.earthAz.toFixed(2)}° / {sgn(now.earthEl)}°</dd>
                <dt>Terrain horizon at Earth azimuth</dt>
                <dd>{sgn(now.earthHorizon)}°</dd>
                <dt>Libration lat / lon</dt>
                <dd>{sgn(P.ephemeris(tNow).subEarthLat)}° / {sgn(P.ephemeris(tNow).subEarthLon)}°</dd>
                <dt>Slant range</dt>
                <dd>{Math.round(now.earthRangeKm).toLocaleString("en-US")} km</dd>
                <dt>Free-space path loss (S-band)</dt>
                <dd>{now.fsplDb.toFixed(1)} dB</dd>
                <dt>Link margin</dt>
                <dd className={isFinite(now.linkMarginDb) ? "" : "crimson"}>{isFinite(now.linkMarginDb) ? sgn(now.linkMarginDb, 1) + " dB" : "NO LINK"}</dd>
              </dl>
            </Panel>
          )}

        </div>
      </main>

      <footer className="foot">
        <span>Sun and Earth: {feed === "live" ? "JPL Horizons live feed" : "analytic ephemeris, within 0.06° of JPL Horizons"}. Terrain and horizon masks: NASA LRO LOLA elevation models.</span>
        <span>Azimuth is measured from true local north, clockwise through east.</span>
        <span className="watermark">SYS_ARCH: AI-Generated Prototype (Claude Fable 5.2)</span>
      </footer>

      <div className="survival" role="group" aria-label="Survival gauges" style={appMode === "game" ? { display: "none" } : undefined}>
        <Gauge label="Battery / thermal" value={soc} tone={socPct < 20 ? C.crimson : socPct < 50 ? "#FB923C" : C.cyan} text={socPct + "%"} />
        <Gauge label="Comms link quality" value={now.lock === "BLACKOUT" ? 0 : P.clamp(now.linkMarginDb / 9.6, 0.12, 1)} tone={now.lock === "LOCK" ? C.cyan : C.blue} text={now.lock === "BLACKOUT" ? "NO LINK" : Math.round((now.lock === "BLACKOUT" ? 0 : P.clamp(now.linkMarginDb / 9.6, 0.12, 1)) * 100) + "%"} />
        <Gauge label="Solar efficiency" value={now.sunFrac * now.cosEff} tone={C.amber} text={Math.round(now.sunFrac * now.cosEff * 100) + "%"} />
        <div className="warns">
          {crisis?.phase === "lost" && <span className="pulse-crit">LOSS OF VEHICLE</span>}
          {sunEvt.active && sunEvt.hours !== null && sunEvt.hours < 12 && <span className="pulse-crit">ECLIPSE IMMINENT</span>}
          {now.sunFrac <= 0.02 && <span className="pulse-crit">IN ECLIPSE</span>}
          {now.lock === "BLACKOUT" && <span className="pulse-crit">COMMS BLACKOUT</span>}
        </div>
      </div>

      {briefing && <Briefing onClose={() => setBriefing(false)} />}
      {showProv && <Provenance onClose={() => setShowProv(false)} />}
    </div>
  );
}
